(()=>{
 const cs=getComputedStyle;
 const a=document.querySelectorAll('aside')[0];
 const scroll=[...a.querySelectorAll('div')].find(d=>cs(d).padding==='16px 14px');
 const kids=[...scroll.children].map(k=>k.tagName+':'+k.textContent.trim().slice(0,16));
 const rowEls=[...scroll.querySelectorAll('div')].filter(d=>cs(d).padding==='8px 10px');
 const r=rowEls[0];
 const spans=[...r.querySelectorAll('span')];
 const badge=spans.find(s=>cs(s).fontSize==='9.5px');
 const ago=spans[spans.length-1];
 return {kids:kids,rowCount:rowEls.length,
   row:{pad:cs(r).padding,rad:cs(r).borderRadius,gap:cs(r).gap,bg:cs(r).backgroundColor,bd:cs(r).borderTopWidth+' '+cs(r).borderTopColor,h:cs(r).height},
   title:[spans.map(s=>s.textContent.trim()).join('|')],
   badge:{txt:badge.textContent,fs:cs(badge).fontSize,fw:cs(badge).fontWeight,h:cs(badge).height,minW:cs(badge).minWidth,pad:cs(badge).padding,rad:cs(badge).borderRadius,bg:cs(badge).backgroundColor,color:cs(badge).color,ls:cs(badge).letterSpacing},
   ago:{txt:ago.textContent,fs:cs(ago).fontSize,w:cs(ago).width,color:cs(ago).color,align:cs(ago).textAlign},
   icon:{w:cs(spans[0]).width,h:cs(spans[0]).height}};
})()

(()=>{
 const cs=getComputedStyle;
 const a=document.querySelectorAll('aside')[0];
 const hdr=a.firstElementChild.firstElementChild;
 const spans=[...hdr.querySelectorAll('span')];
 const logo=hdr.querySelector('div');
 const b=[...hdr.querySelectorAll('button')][0];
 return {hdrPad:cs(hdr).padding,gap:cs(hdr).gap,w:cs(hdr).width,btn:[cs(b).width,cs(b).height,cs(b).borderRadius],
  logo:[cs(logo).width,cs(logo).height],
  brand:spans.map(s=>[s.textContent.trim(),cs(s).fontFamily,cs(s).fontSize,cs(s).lineHeight])};
})()

(()=>{
 const cs=getComputedStyle;
 const a=document.querySelectorAll('aside')[0];
 const scroll=[...a.querySelectorAll('div')].find(d=>cs(d).padding==='16px 14px');
 const cards=[...scroll.children];
 const c=cards[0];
 const spans=[...c.querySelectorAll('span')];
 const op=[...scroll.querySelectorAll('button')].pop();
 return {n:cards.length,cardCount:cards.length,
  card:{pad:cs(c).padding,rad:cs(c).borderRadius,border:cs(c).borderTopWidth+' '+cs(c).borderTopColor,bg:cs(c).backgroundColor,gap:cs(c).gap},
  spans:spans.map(s=>[s.textContent.trim().slice(0,30),cs(s).fontSize,cs(s).fontFamily,cs(s).padding,cs(s).borderRadius,cs(s).backgroundColor,cs(s).color]),
  openFolder:[op.textContent.trim(),cs(op).padding,cs(op).borderRadius,cs(op).borderTopStyle,cs(op).borderTopColor,cs(op).fontSize,cs(op).color,cs(op).textAlign]};
})()

(()=>{
 const cs=getComputedStyle;
 const dlg=[...document.querySelectorAll('div')].find(d=>(d.getAttribute('style')||'').indexOf('width: 1320px')>=0);
 if(!dlg) return 'not open';
 const overlay=dlg.parentElement;
 const nav=dlg.querySelector('nav');
 const hdr=dlg.querySelector('header');
 const knobEls=[...dlg.querySelectorAll('span')].filter(s=>cs(s).width==='18px'&&cs(s).borderRadius==='9px');
 return {overlayBg:cs(overlay).backgroundColor,overlayPad:cs(overlay).paddingTop,
  dlg:[cs(dlg).width,cs(dlg).height,cs(dlg).borderRadius,cs(dlg).backgroundColor,cs(dlg).boxShadow,cs(dlg).borderTopWidth+' '+cs(dlg).borderTopColor],
  nav:[cs(nav).width,cs(nav).padding,cs(nav).borderRight,cs(nav).backgroundColor,cs(nav).gap],
  hdr:[cs(hdr).padding,cs(hdr).borderBottom,cs(hdr).gap],
  track:knobEls.length?[cs(knobEls[0]).width,cs(knobEls[0]).height,cs(knobEls[0]).borderRadius,cs(knobEls[0]).transition,cs(knobEls[0]).backgroundColor]:null,
  knob:knobEls.length?[cs(knobEls[0].firstElementChild).transition,cs(knobEls[0].firstElementChild).left,cs(knobEls[0].firstElementChild).width,cs(knobEls[0].firstElementChild).borderRadius]:null};
})()
